async function getPosts(element?: string): Promise<Post[]> {
  const filter = element ? `&& element == $element` : ''
  const query = groq`*[_type == "post" ${filter}] | order(publishedAt desc) {
    _id,
    title,
    slug,
    element,
    excerpt,
    description,
    mainImage,
    publishedAt
  }`

  try {
    const data = await client.fetch(query, { element }, { next: { revalidate: 60 } })
    // If no real data, return mock data filtered by element
    if (!data || data.length === 0) {
      return mockPosts.filter(p => !element || p.element === element)
    }
    return data
  } catch (error) {
    console.error("Failed to fetch posts:", error)
    return mockPosts.filter(p => !element || p.element === element)
  }
}

